#!/usr/bin/env python3
"""Validation script for Canonical DSL v1.1 Scratch project scripts.

This script validates the generated DSL JSON against the spec requirements:
- Top-level structure compliance
- Script object validation (hat, hatId, blocks)
- Hat opcode validity
- Opcode formatting
- Variable name cross-referencing against project_metadata.json
"""

import json
import sys
from typing import Dict, List, Any, Set, Tuple

# Valid hat opcodes per Canonical DSL v1.1 spec
VALID_HAT_OPCODES = {
    "event_whenflagclicked",
    "control_start_as_clone",
    "event_whenbroadcastreceived",
    "event_whenkeypressed"
}

def load_json(path: str) -> Dict:
    """Load and parse a JSON file."""
    with open(path, 'r', encoding='utf-8') as f:
        return json.load(f)

def get_variable_names(metadata: Dict) -> Set[str]:
    """Extract all variable names from project metadata."""
    return {v["name"] for v in metadata.get("variables", [])}

def validate_top_level(dsl: Dict) -> Tuple[bool, str]:
    """Check that top-level structure is {"scripts": [...]}."""
    if not isinstance(dsl, dict):
        return False, "Root must be a dictionary"
    if "scripts" not in dsl:
        return False, "Missing required key 'scripts'"
    if not isinstance(dsl["scripts"], list):
        return False, "'scripts' must be an array"
    # Check no unexpected keys
    if set(dsl.keys()) != {"scripts"}:
        return False, f"Unexpected keys in root: {set(dsl.keys()) - {'scripts'} }"
    return True, "OK"

def validate_script_object(script: Dict, index: int, all_hat_ids: Set[str]) -> List[str]:
    """Validate a single script object. Returns list of error messages."""
    errors = []

    # Check required fields
    for field in ["hat", "hatId", "blocks"]:
        if field not in script:
            errors.append(f"Script[{index}]: Missing required field '{field}'")

    if errors:
        return errors

    # Validate hat opcode
    hat = script["hat"]
    if hat not in VALID_HAT_OPCODES:
        errors.append(f"Script[{index}]: Invalid hat opcode '{hat}'. Must be one of: {sorted(VALID_HAT_OPCODES)}")

    # Validate hatId
    hat_id = script["hatId"]
    if not isinstance(hat_id, str) or not hat_id:
        errors.append(f"Script[{index}]: 'hatId' must be a non-empty string")
    elif hat_id in all_hat_ids:
        errors.append(f"Script[{index}]: Duplicate hatId '{hat_id}'")
    all_hat_ids.add(hat_id)

    # Validate blocks is an array
    blocks = script["blocks"]
    if not isinstance(blocks, list):
        errors.append(f"Script[{index}]: 'blocks' must be an array")

    return errors

def validate_block(block: Dict, depth: int = 0, valid_opcodes: Set[str] = None) -> List[str]:
    """Recursively validate a block and its nested blocks."""
    errors = []

    if depth > 20:  # Prevent infinite recursion
        return ["Maximum nesting depth exceeded"]

    if not isinstance(block, dict):
        return ["Block must be a dictionary"]

    if "opcode" not in block:
        return ["Block missing required field 'opcode'"]

    opcode = block["opcode"]

    # Check for opcode registry (we allow any valid Scratch opcode pattern)
    # The spec allows standard Scratch opcodes
    allowed_prefixes = ["event_", "control_", "motion_", "looks_", "sensing_", "data_", "operator_"]
    if not any(opcode.startswith(p) for p in allowed_prefixes):
        errors.append(f"Unknown opcode prefix for '{opcode}'")

    # Validate SUBSTACK inputs/fields are present if required
    inputs = block.get("inputs", {})
    fields = block.get("fields", {})

    # Check SUBSTACK blocks
    if "SUBSTACK" in inputs:
        substack = inputs["SUBSTACK"]
        if not isinstance(substack, list):
            errors.append(f"SUBSTACK for opcode '{opcode}' must be an array")
        else:
            for sub_block in substack:
                errors.extend(validate_block(sub_block, depth + 1))

    # Check CONDITION blocks (for control_if, control_repeat_until)
    if "CONDITION" in inputs:
        condition = inputs["CONDITION"]
        if isinstance(condition, dict) and "opcode" in condition:
            errors.extend(validate_block(condition, depth + 1))

    # Check ELSE_SUBSTACK if present (for our extended if-else)
    if "ELSE_SUBSTACK" in inputs:
        else_substack = inputs["ELSE_SUBSTACK"]
        if isinstance(else_substack, list):
            for sub_block in else_substack:
                errors.extend(validate_block(sub_block, depth + 1))

    return errors

def extract_used_variables(blocks: List[Dict]) -> Set[str]:
    """Extract all variable names used in blocks."""
    variables = set()

    def recurse(block: Dict):
        if not isinstance(block, dict):
            return

        # Check fields for VARIABLE
        fields = block.get("fields", {})
        if "VARIABLE" in fields:
            var_name = fields["VARIABLE"]
            if isinstance(var_name, str):
                variables.add(var_name)

        # Recurse into inputs
        inputs = block.get("inputs", {})
        for key, value in inputs.items():
            if isinstance(value, dict) and "opcode" in value:
                recurse(value)
            elif isinstance(value, list):
                for item in value:
                    if isinstance(item, dict) and "opcode" in item:
                        recurse(item)

    for block in blocks:
        recurse(block)

    return variables

def validate_variable_usage(dsl: Dict, metadata: Dict) -> Tuple[List[str], List[str]]:
    """Check variable usage against project metadata. Returns (errors, warnings)."""
    defined_vars = get_variable_names(metadata)
    used_vars = set()

    for script in dsl.get("scripts", []):
        blocks = script.get("blocks", [])
        used_vars.update(extract_used_variables(blocks))

    errors = []
    warnings = []

    # Check for undefined variables (excluding internal Scratch values like _mouse_, _edge_)
    for var in used_vars:
        if var.startswith("_"):
            # Internal Scratch variable/boundary, skip
            continue
        if var not in defined_vars:
            errors.append(f"Variable '{var}' used but not defined in project_metadata.json. Defined: {sorted(defined_vars)}")

    # Warn about defined but unused variables
    unused = defined_vars - used_vars
    for var in sorted(unused):
        warnings.append(f"Variable '{var}' defined in metadata but never used in scripts")

    return errors, warnings

def validate_opcodes_format(dsl: Dict) -> List[str]:
    """Check that opcodes use correct lowercase-with-underscore format."""
    errors = []

    def check_opcode(opcode: str, path: str):
        if not opcode.islower() or "_" not in opcode:
            errors.append(f"Opcode '{opcode}' at {path} doesn't follow lowercase-with-underscore format")

    def recurse(block: Dict, path: str):
        if not isinstance(block, dict):
            return
        opcode = block.get("opcode", "")
        check_opcode(opcode, path)

        inputs = block.get("inputs", {})
        for key, value in inputs.items():
            if isinstance(value, dict) and "opcode" in value:
                recurse(value, f"{path}.{key}")
            elif isinstance(value, list):
                for i, item in enumerate(value):
                    if isinstance(item, dict) and "opcode" in item:
                        recurse(item, f"{path}.{key}[{i}]")

    for i, script in enumerate(dsl.get("scripts", [])):
        for j, block in enumerate(script.get("blocks", [])):
            recurse(block, f"scripts[{i}].blocks[{j}]")

    return errors

def validate_dsl(dsl_path: str, metadata_path: str) -> Dict:
    """Full validation pipeline."""
    result = {
        "passed": True,
        "summary": {},
        "errors": [],
        "warnings": []
    }

    # Load files
    try:
        dsl = load_json(dsl_path)
    except Exception as e:
        result["passed"] = False
        result["errors"].append(f"Failed to load DSL file: {e}")
        return result

    try:
        metadata = load_json(metadata_path)
    except Exception as e:
        result["warnings"].append(f"Failed to load metadata file: {e}. Variable validation skipped.")
        metadata = {}

    # 1. Top-level structure
    top_ok, top_msg = validate_top_level(dsl)
    if not top_ok:
        result["passed"] = False
        result["errors"].append(f"Top-level structure: {top_msg}")
    result["summary"]["top_level"] = "PASS" if top_ok else "FAIL"

    # 2. Script objects
    all_hat_ids = set()
    script_errors = []
    scripts = dsl.get("scripts", [])
    result["summary"]["script_count"] = len(scripts)

    for i, script in enumerate(scripts):
        errors = validate_script_object(script, i, all_hat_ids)
        script_errors.extend(errors)

    if script_errors:
        result["passed"] = False
        result["errors"].extend(script_errors)
    result["summary"]["script_validation"] = "PASS" if not script_errors else "FAIL"

    # 3. Block validation
    block_errors = []
    for i, script in enumerate(scripts):
        for j, block in enumerate(script.get("blocks", [])):
            errors = validate_block(block, path=f"script[{i}].block[{j}]")
            block_errors.extend(errors)

    if block_errors:
        result["passed"] = False
        result["errors"].extend(block_errors)
    result["summary"]["block_validation"] = "PASS" if not block_errors else "FAIL"

    # 4. Opcode format
    opcode_errors = validate_opcodes_format(dsl)
    if opcode_errors:
        result["warnings"].extend(opcode_errors)
    result["summary"]["opcode_format"] = "PASS" if not opcode_errors else "WARN"

    # 5. Variable cross-reference
    if metadata:
        var_errors, var_warnings = validate_variable_usage(dsl, metadata)
        if var_errors:
            result["passed"] = False
            result["errors"].extend(var_errors)
        result["warnings"].extend(var_warnings)
        result["summary"]["variable_validation"] = "PASS" if not var_errors else "FAIL"
    else:
        result["summary"]["variable_validation"] = "SKIPPED"

    return result

def main():
    dsl_path = "output/scratch_dsl_script.json"
    metadata_path = "config/project_metadata.json"

    print(f"Validating DSL: {dsl_path}")
    print(f"Using metadata: {metadata_path}")
    print("=" * 60)

    result = validate_dsl(dsl_path, metadata_path)

    # Print summary
    print("\nValidation Summary:")
    for key, value in result["summary"].items():
        print(f"  {key}: {value}")

    # Print errors
    if result["errors"]:
        print(f"\nErrors ({len(result['errors'])}):")
        for error in result["errors"]:
            print(f"  ❌ {error}")

    # Print warnings
    if result["warnings"]:
        print(f"\nWarnings ({len(result['warnings'])}):")
        for warning in result["warnings"]:
            print(f"  ⚠️  {warning}")

    # Final result
    print("\n" + "=" * 60)
    if result["passed"]:
        print("✅ VALIDATION PASSED")
        sys.exit(0)
    else:
        print("❌ VALIDATION FAILED")
        sys.exit(1)

if __name__ == "__main__":
    main()
